WITH filtered AS (SELECT id, order_id, method, amount, paid_at, status, COALESCE(method, 'unassigned') AS method_filled FROM payments WHERE paid_at >= TIMESTAMP '2023-05-28 20:00:00'), with_gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) > INTERVAL '60' DAY THEN 1 ELSE 0 END AS is_new_session FROM filtered), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT DATE_TRUNC('MONTH', paid_at) AS activity_month, MAX(paid_at) AS last_paid_at, ROUND(SUM(session_id) / NULLIF(COUNT(CASE WHEN status = 'REFUNDED' THEN 1 END), 0), 2) AS session_id_per_refunded, STDDEV_SAMP(amount) AS amount_stddev, SIZE(COLLECT_SET(status)) AS num_status, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS span_minutes, SIZE(COLLECT_SET(method)) AS num_methods FROM sessionized GROUP BY activity_month;
